import{c as t,Q as a,j as s,m as n}from"./chunks/framework.BXc4yaFE.js";const p=JSON.parse('{"title":"Evolving Agents in the Dark: Retrospective Harness Optimization via Self-Preference","description":"","frontmatter":{"url":"https://arxiv.org/abs/2606.05922","title":"Evolving Agents in the Dark: Retrospective Harness Optimization via Self-Preference","archived_date":"2026-06-14T00:00:00.000Z","arxiv_id":2606.05922,"authors":["Wenbo Pan","Shujie Liu","Chin-Yew Lin","Jingying Zeng","Xianfeng Tang","Xiangyang Zhou","Yan Lu","Xiaohua Jia"],"pdf_path":"pdfs/2606.05922.pdf","published_date":"2026-06-04T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2026-06-04-retrospective-harness-optimization-rho-2606-05922.md","filePath":"research/papers/2026-06-04-retrospective-harness-optimization-rho-2606-05922.md","lastUpdated":1785909234000}'),r={name:"research/papers/2026-06-04-retrospective-harness-optimization-rho-2606-05922.md"};function i(o,e,l,c,g,d){return a(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="evolving-agents-in-the-dark-retrospective-harness-optimization-via-self-preference" tabindex="-1">Evolving Agents in the Dark: Retrospective Harness Optimization via Self-Preference <a class="header-anchor" href="#evolving-agents-in-the-dark-retrospective-harness-optimization-via-self-preference" aria-label="Permalink to &quot;Evolving Agents in the Dark: Retrospective Harness Optimization via Self-Preference&quot;">​</a></h1><p><strong>Authors</strong>: Wenbo Pan, Shujie Liu, Chin-Yew Lin, Jingying Zeng, Xianfeng Tang, Xiangyang Zhou, Yan Lu, Xiaohua Jia <strong>Published</strong>: June 2026 <strong>Source</strong>: <a href="https://arxiv.org/abs/2606.05922" target="_blank" rel="noreferrer">https://arxiv.org/abs/2606.05922</a><strong>arXiv ID</strong>: 2606.05922 <strong>Categories</strong>: not specified in fetched content</p><hr><h2 id="abstract" tabindex="-1">Abstract <a class="header-anchor" href="#abstract" aria-label="Permalink to &quot;Abstract&quot;">​</a></h2><p>RHO (Retrospective Harness Optimization) is a self-supervised technique for improving AI agent capabilities through past task data rather than requiring labeled validation sets. The method selects challenging previous tasks, re-executes them, and leverages the agent&#39;s own judgment to identify and implement the most beneficial harness updates, achieving significant performance gains on software engineering benchmarks without external evaluation.</p><p><em>(Note: verbatim abstract not available in fetched content; above is a summary reconstruction from cached fetch.)</em></p><hr><h2 id="key-findings" tabindex="-1">Key Findings <a class="header-anchor" href="#key-findings" aria-label="Permalink to &quot;Key Findings&quot;">​</a></h2><ul><li><strong>SWE-Bench Pro</strong>: Baseline 59% → RHO 78% (+19 percentage points), using 103 agent calls, zero validation labels required.</li><li><strong>Terminal-Bench 2</strong>: Baseline 71% → RHO 76% (+5 percentage points).</li><li><strong>GAIA-2</strong>: Baseline 29% → RHO 37% (+8 percentage points).</li><li><strong>vs. Meta-Harness (1 round, with labels)</strong>: RHO 78% vs. Meta-Harness 62%, despite Meta-Harness requiring held-out labeled data; RHO uses 103 vs. 41 agent calls (2.5× more calls, but label-free).</li><li><strong>vs. Multi-round Meta-Harness (10 rounds)</strong>: Meta-Harness reached 80% but required ~320 agent calls (3.1× RHO&#39;s budget) plus held-out labels.</li><li><strong>Ablation — coreset strategy</strong> (Figure 5): Pure difficulty = no improvement (stayed at ~59%); pure diversity = suboptimal; DPP balance at θ=0.7 = optimal +19% gain.</li><li><strong>Ablation — diagnostic signals</strong> (Table 4, SWE-Bench Pro): Full diagnosis = 78%; without self-consistency = 56%; without self-validation = 70%; raw trajectory (no diagnosis) = 60%.</li><li><strong>Candidate variance</strong> (Table 3): Lowest-scoring candidate still improved over baseline (0.73 vs. 0.59); selected candidate = 0.78; std ~0.06 across three candidates.</li></ul><h2 id="self-preference-mechanism-no-ground-truth" tabindex="-1">Self-Preference Mechanism (no ground-truth) <a class="header-anchor" href="#self-preference-mechanism-no-ground-truth" aria-label="Permalink to &quot;Self-Preference Mechanism (no ground-truth)&quot;">​</a></h2><p>RHO operates in three stages using only past trajectories, with no external oracle:</p><p><strong>1. Coreset Selection</strong>: Selects k=10 challenging, diverse tasks from past trajectories using a Determinantal Point Process (DPP) kernel (θ=0.7 difficulty, 0.3 diversity). A language model &quot;difficulty judge&quot; scores complexity and extracts failure-mode fingerprints.</p><p><strong>2. Group Rollout &amp; Diagnosis</strong>: For each coreset task, the agent generates G=3 parallel solution attempts. Two self-referential diagnostic signals are extracted:</p><ul><li><em>Self-validation</em>: Agent inspects each trajectory for correctness issues — &quot;incorrect tool invocations, false assumptions, and premature stopping.&quot;</li><li><em>Self-consistency</em>: Agent identifies contradictions across parallel trajectories, flagging &quot;divergent plans, tool sequences, or final answers.&quot; Diagnosed issues are ranked by severity ∈ [0,1] as soft attention weights.</li></ul><p><strong>3. Best-of-N Harness Selection</strong>: N=3 candidate harnesses are generated from diagnosed weaknesses. Each candidate is tested on the 10 coreset tasks. <strong>Acceptance gate</strong>: pairwise ranking where the agent compares candidate trajectories against baseline trajectories on the same task, producing scores in [−10, 10]. A candidate is accepted <strong>only if mean pairwise score &gt; 0</strong>; zero or negative scores trigger no update (rejection).</p><p><strong>Core principle</strong>: &quot;The agent&#39;s own trajectories already contain the signal needed to improve it, since re-solving past tasks and comparing the outcomes exposes where the harness fails.&quot;</p><p><strong>Critical limitation</strong>: RHO assumes environments that &quot;reset cleanly and tolerate repeated attempts,&quot; excluding one-shot or irreversible tasks. In open environments, past trajectories can embed adversarial content injected mid-task, requiring &quot;human approval for sensitive harness edits.&quot;</p><h2 id="quantified-conditions" tabindex="-1">Quantified Conditions <a class="header-anchor" href="#quantified-conditions" aria-label="Permalink to &quot;Quantified Conditions&quot;">​</a></h2><ul><li><strong>Coreset size</strong>: k = 10 tasks</li><li><strong>Parallel rollouts per task</strong>: G = 3</li><li><strong>Candidate harnesses generated</strong>: N = 3</li><li><strong>Acceptance threshold</strong>: mean pairwise ranking score strictly &gt; 0 (integer scale [−10, 10])</li><li><strong>DPP balance parameter</strong>: θ = 0.7 (70% difficulty, 30% diversity)</li><li><strong>Severity weighting</strong>: soft attention weights ∈ [0, 1], not hard thresholds</li><li><strong>Orbit timeout</strong>: 900 seconds (SWE-Bench Pro), 300 seconds (Terminal-Bench 2), dataset-specific for GAIA-2</li></ul><h2 id="relevance-to-the-loop-harness-self-improvement" tabindex="-1">Relevance to The Loop (harness self-improvement) <a class="header-anchor" href="#relevance-to-the-loop-harness-self-improvement" aria-label="Permalink to &quot;Relevance to The Loop (harness self-improvement)&quot;">​</a></h2><p>RHO is a direct empirical instantiation of the RECORD→OBSERVE→APPLY loop for harness self-improvement: it replaces external ground-truth labels with self-consistency signals across multiple rollouts, addressing precisely the <code>unverified_success</code> problem. The acceptance gate (pairwise score &gt; 0, agent-judged) is an oracle-free verdict mechanism — analogous to the workspace rule that &quot;subagent/workflow verdict ≠ evidence; must grep-verify.&quot; The critical caveat that RHO requires clean-resettable environments and excludes one-shot/irreversible tasks directly maps to The Loop&#39;s &quot;APPLY gate for destructive/irreversible changes&quot; — self-preference cannot substitute for external verification in non-resettable contexts. The human-approval requirement for sensitive harness edits in open environments mirrors the workspace&#39;s P0 hotfix gate and production safety redlines.</p>',21)])])}const u=t(r,[["render",i]]);export{p as __pageData,u as default};
